// micropython
ACMsg.MPY_MICROPYTHON_MODULE = "Module micropython : accès et contrôle d'éléments internes de MicroPython.";
ACMsg.MPY_MICROPYTHON_CONST = "D\u00e9clare que l\u2019expression est une constante afin que le compilateur puisse l\u2019optimiser. Usage typique : from micropython import const; CONST_X = const(123); CONST_Y = const(2 * CONST_X + 1). Les constantes ainsi d\u00e9clar\u00e9es restent accessibles comme variables globales depuis l\u2019ext\u00e9rieur du module o\u00f9 elles sont d\u00e9finies. Si le nom commence par '_' alors la constante est cach\u00e9e (non disponible comme variable globale) et ne consomme pas de m\u00e9moire \u00e0 l\u2019ex\u00e9cution. const() est reconnue directement par le parseur MicroPython et est fournie surtout pour \u00e9crire des scripts compatibles CPython/MicroPython en suivant le m\u00eame sch\u00e9ma.";
ACMsg.MPY_MICROPYTHON_OPT_LEVEL = "Lit ou définit le niveau d'optimisation utilisé pour les compilations suivantes. Si level est fourni, fixe le niveau et renvoie None ; sinon renvoie le niveau courant. Cela contrôle : les assertions (niveau 0 : actives et compilées ; niveau 1+ : non compilées) ; la variable intégrée __debug__ (niveau 0 : True ; niveau 1+ : False) ; et le stockage des numéros de ligne source avec le bytecode (niveaux 0/1/2 : stockés pour que les exceptions puissent indiquer la ligne ; niveau 3+ : non stockés). Le niveau par défaut est généralement 0.";
ACMsg.MPY_MICROPYTHON_OPT_LEVEL = "Si level est fourni, d\u00e9finit le niveau d\u2019optimisation pour les compilations suivantes et renvoie None. Sinon, renvoie le niveau d\u2019optimisation courant. Le niveau d\u2019optimisation contr\u00f4le : les assertions (niveau 0 : les assertions sont activ\u00e9es et compil\u00e9es ; niveaux 1 et plus : elles ne sont pas compil\u00e9es) ; la variable int\u00e9gr\u00e9e __debug__ (niveau 0 : vaut True ; niveaux 1 et plus : vaut False) ; et la conservation des num\u00e9ros de ligne dans le bytecode (niveaux 0, 1 et 2 : num\u00e9ros de ligne stock\u00e9s pour que les exceptions puissent indiquer la ligne ; niveaux 3 et plus : num\u00e9ros de ligne non stock\u00e9s). Le niveau par d\u00e9faut est g\u00e9n\u00e9ralement 0.";
ACMsg.MPY_MICROPYTHON_MEM_INFO = "Affiche des informations sur la mémoire utilisée. Si l'argument optionnel verbose est fourni, des informations supplémentaires sont affichées. Le contenu exact dépend du port, mais inclut généralement l'usage du stack et du heap ; en mode verbose, un dump complet du heap peut indiquer les blocs utilisés et les blocs libres.";
ACMsg.MPY_MICROPYTHON_QSTR_INFO = "Affiche des informations sur les chaînes internées (qstr). Si l'argument optionnel verbose est fourni, des informations supplémentaires sont affichées. Le contenu exact dépend du port, mais inclut généralement le nombre de chaînes internées et la quantité de RAM utilisée ; en mode verbose, les noms des chaînes internées en RAM sont listés.";
ACMsg.MPY_MICROPYTHON_STACK_USE = "Renvoie un entier représentant l'usage courant de la pile (stack). La valeur absolue est rarement utile ; on l'utilise surtout pour comparer l'usage de la pile entre différents points du programme.";
ACMsg.MPY_MICROPYTHON_HEAP_LOCK = "Verrouille le heap. Lorsqu'il est verrouillé, aucune allocation ne peut avoir lieu et une tentative d'allocation lèvera MemoryError. heap_lock() peut être imbriqué (appelé plusieurs fois) et augmente une profondeur de verrouillage interne ; heap_unlock() doit être appelé autant de fois pour rendre le heap à nouveau disponible. Si le REPL devient actif alors que le heap est verrouillé, il sera déverrouillé de force.";
ACMsg.MPY_MICROPYTHON_HEAP_UNLOCK = "Déverrouille le heap (imbriquable). Renvoie la profondeur actuelle après déverrouillage ; 0 signifie que le heap n'est pas verrouillé.";
ACMsg.MPY_MICROPYTHON_HEAP_LOCKED = "Renvoie la profondeur de verrouillage du heap sous forme d'entier >= 0 (0 = non verrouillé). Remarque : heap_locked() n'est pas activé sur la plupart des ports par défaut et peut nécessiter une option de compilation.";
ACMsg.MPY_MICROPYTHON_KBD_INTR = "Définit le code caractère qui déclenche une exception KeyboardInterrupt. Par défaut : 3 pendant l'exécution d'un script (Ctrl-C). Passer -1 désactive la capture de Ctrl-C ; passer 3 la réactive. Utile pour empêcher la capture de Ctrl-C sur le flux de caractères entrant généralement utilisé par le REPL si ce flux est utilisé à d'autres fins.";
ACMsg.MPY_MICROPYTHON_SCHEDULE = "Planifie l\u2019ex\u00e9cution de la fonction func \u00ab tr\u00e8s bient\u00f4t \u00bb. La fonction re\u00e7oit arg comme unique argument. \u00ab Tr\u00e8s bient\u00f4t \u00bb signifie que le runtime tentera de l\u2019ex\u00e9cuter le plus t\u00f4t possible tout en restant efficace, et sous les conditions suivantes : une fonction planifi\u00e9e ne pr\u00e9empte jamais une autre fonction planifi\u00e9e ; les fonctions planifi\u00e9es s\u2019ex\u00e9cutent entre des opcodes, ce qui rend atomiques les op\u00e9rations Python fondamentales (comme ajouter \u00e0 une liste) ; et un port peut d\u00e9finir des r\u00e9gions critiques o\u00f9 les fonctions planifi\u00e9es ne s\u2019ex\u00e9cutent pas (elles peuvent y \u00eatre planifi\u00e9es mais ne s\u2019ex\u00e9cuteront qu\u2019\u00e0 la sortie de la r\u00e9gion \u2014 exemple : un handler IRQ pr\u00e9emptif). Un usage courant est de planifier un callback depuis une IRQ pr\u00e9emptive : on \u00e9vite ainsi les contraintes d\u2019une IRQ (par ex. heap verrouill\u00e9) en reportant le travail. Sur les ports multi-threads, le comportement d\u00e9pend du Global Interpreter Lock (GIL) : si le GIL est activ\u00e9, la fonction planifi\u00e9e peut pr\u00e9empter n\u2019importe quel thread et s\u2019ex\u00e9cuter dans son contexte ; s\u2019il est d\u00e9sactiv\u00e9, elle ne pr\u00e9empte que le thread principal. Remarque : si schedule() est appel\u00e9e depuis une IRQ pr\u00e9emptive o\u00f9 l\u2019allocation m\u00e9moire est interdite et que le callback est une m\u00e9thode li\u00e9e (bound method), le passage direct peut \u00e9chouer car cr\u00e9er la r\u00e9f\u00e9rence de m\u00e9thode li\u00e9e alloue de la m\u00e9moire ; une solution consiste \u00e0 cr\u00e9er/stocker la r\u00e9f\u00e9rence \u00e0 la m\u00e9thode dans le constructeur de la classe, puis \u00e0 planifier cette r\u00e9f\u00e9rence stock\u00e9e. La file d\u2019attente des callbacks planifi\u00e9s est de taille finie : schedule() l\u00e8ve RuntimeError si elle est pleine.";
ACMsg.MPY_MICROPYTHON_RINGIO = "RingIO fournit un ringbuffer de bytes de taille fixe avec une interface de type flux, comparable \u00e0 une variante FIFO de io.BytesIO. On peut le construire avec une taille enti\u00e8re (allocation interne d\u2019un buffer adapt\u00e9) ou fournir un objet compatible buffer protocol comme un bytearray pour l\u2019utiliser in-place. L\u2019algorithme classique de ringbuffer r\u00e9serve un octet pour le suivi : avec une taille enti\u00e8re, ce surco\u00fbt est pris en compte (ex. RingIO(16) alloue 17 octets en interne pour pouvoir stocker 16 octets), mais avec un buffer pr\u00e9allou\u00e9 on ne peut stocker qu\u2019un octet de moins que sa longueur (ex. RingIO(bytearray(16)) ne stocke que 15 octets). Une instance RingIO peut \u00eatre s\u00fbre en IRQ/thread si elle sert \u00e0 faire transiter les donn\u00e9es dans un seul sens (par ex. \u00e9criture en IRQ, lecture hors IRQ, ou l\u2019inverse). Ce n\u2019est plus garanti si on \u00e9crit dans la m\u00eame instance \u00e0 la fois en IRQ et hors IRQ, ce qui peut entra\u00eener des corruptions de donn\u00e9es.";
ACMsg.MPY_MICROPYTHON_RINGIO_ANY = "Renvoie un entier indiquant le nombre d'octets disponibles à la lecture. Retour : int.";
ACMsg.MPY_MICROPYTHON_RINGIO_READ = "Lit les octets disponibles (non bloquant). Si nbytes est fourni, lit au plus nbytes octets ; sinon lit un maximum. Retour : un objet bytes (bytes vide si aucune donnée n'est disponible)." ;
ACMsg.MPY_MICROPYTHON_RINGIO_READLINE = "Lit une ligne se terminant par un caractère de fin de ligne (\n) (ou retourne si présent dans le buffer) ; sinon renvoie les octets disponibles. Si nbytes est fourni, lit au plus nbytes octets. Retour : bytes.";
ACMsg.MPY_MICROPYTHON_RINGIO_READINTO = "Lit des octets disponibles dans buf. Si nbytes est fourni, lit au plus nbytes ; sinon lit au plus len(buf). Retour : int (nombre d'octets lus dans buf)." ;
ACMsg.MPY_MICROPYTHON_RINGIO_WRITE = "Écrit des octets depuis buf vers le ringbuffer (non bloquant), limité par l'espace libre. Retour : int (nombre d'octets écrits)." ;
ACMsg.MPY_MICROPYTHON_RINGIO_CLOSE = "No-op pour compatibilité avec l'interface stream standard ; n'a aucun effet sur les données du ringbuffer." ;
ACMsg.MPY_MICROPYTHON_NATIVE_DECORATOR = "Compile la fonction décorée en code machine natif (au lieu du bytecode). Souvent plus rapide, mais consomme plus de mémoire et impose des limitations (certaines fonctionnalités Python sont restreintes). Selon le port/firmware, peut être indisponible.";
ACMsg.MPY_MICROPYTHON_VIPER_DECORATOR = "Compile la fonction via l'émetteur Viper pour de meilleures performances, surtout sur les entiers et les opérations bit à bit. Utilise des types natifs Viper et n'est pas totalement compatible Python. Selon le port/firmware, peut être indisponible.";
ACMsg.MPY_MICROPYTHON_ASM_THUMB_DECORATOR = "Définit une fonction en assembleur inline pour les cibles ARM Thumb/Thumb-2. Le corps de fonction utilise le DSL assembleur de MicroPython. Disponible uniquement sur les firmwares ARM compatibles.";
ACMsg.MPY_MICROPYTHON_ASM_XTENSA_DECORATOR = "Définit une fonction en assembleur inline pour les cibles Xtensa (ex. certains firmwares ESP8266/ESP32). Disponible uniquement si le firmware active l'assembleur inline Xtensa.";
ACMsg.MPY_MICROPYTHON_ASM_RV32_DECORATOR = "Définit une fonction en assembleur inline pour les cibles RISC-V 32 bits (RV32) lorsque le port/firmware l'active (ex. certaines configurations rp2 en mode RISC-V).";
// neopixel
ACMsg.MPY_NEOPIXEL_WS2812_WRITE = "Écrit le buffer <b>buf</b> (bytes/bytearray) sur une bande WS2812 connectée à la broche <b>pin</b>.";
ACMsg.MPY_NEOPIXEL_NEOPIXEL = "Classe pour piloter une bande NeoPixel (WS2812). Crée une instance avec <b>pin</b>, <b>n</b> LEDs et <b>bpp</b> octets par pixel (par défaut <b>3</b>, ou <b>4</b> pour RGBW). Returns: <b>NeoPixel</b>.";
ACMsg.MPY_NEOPIXEL_NEOPIXEL_INDEX = "Accès par index : lire/écrire une LED avec <b>strip[i]</b> (ex : <b>np[0] = (255, 0, 0)</b>).";
ACMsg.MPY_NEOPIXEL_ORDER = "Constante d'ordre des canaux de couleur (par ex. RGB/GRB) utilisée par certains NeoPixels. Returns: <b>int</b>.";
ACMsg.MPY_NEOPIXEL_INIT = "Crée une guirlande NeoPixel pilotée par <b>pin</b> avec <b>n</b> LEDs. <b>bpp</b> indique le nombre d'octets par pixel (par défaut <b>3</b> pour RGB, <b>4</b> pour RGBW). Returns: <b>NeoPixel</b>.";
ACMsg.MPY_NEOPIXEL_CLEAR = "Éteint toutes les LEDs (remplit le buffer avec 0). Pense à appeler <b>show()</b> ou <b>write()</b> pour rendre la mise à jour visible.";
ACMsg.MPY_NEOPIXEL_SHOW = "Envoie le buffer courant vers la guirlande et affiche les couleurs. À appeler après avoir modifié les pixels.";
