ACMsg.MPY_NEOPIXEL_FILL = "Colore toutes les LEDs avec <b>colour</b> (tuple RGB/RGBW de longueur <b>bpp</b>, ex: <b>(0,0,255)</b>). Utilise ensuite <b>show()</b> ou <b>write()</b>.";
ACMsg.MPY_NEOPIXEL_GETITEM = "Retourne la couleur du pixel à l'index <b>index</b> sous forme de tuple RGB/RGBW. Returns: <b>tuple</b>.";
ACMsg.MPY_NEOPIXEL_SETITEM = "Définit le pixel à l'index <b>index</b> avec la couleur <b>colour</b> (tuple RGB/RGBW). N'oublie pas <b>show()</b> ou <b>write()</b>.";
ACMsg.MPY_NEOPIXEL_LEN = "Retourne le nombre de LEDs dans la guirlande (utilisable avec <b>len(np)</b>). Returns: <b>int</b>.";
// bluetooth
ACMsg.MPY_BLUETOOTH_BLE = "Interface BLE bas niveau. <b>bluetooth.BLE()</b> retourne l'objet driver singleton. Returns: <b>BLE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_ACTIVE = "Active/désactive la radio BLE (argument optionnel) et retourne l'état courant. La radio doit être active avant d'utiliser les autres méthodes. Returns: <b>bool</b>.";
ACMsg.MPY_BLUETOOTH_BLE_CONFIG = "Lit/modifie la configuration BLE. Lire avec <b>config('param')</b>, écrire avec des mots-clés <b>config(param=value,...)</b>. Paramètres supportés : <b>'mac'</b>, <b>'addr_mode'</b>, <b>'gap_name'</b>, <b>'rxbuf'</b>, <b>'mtu'</b>, <b>'bond'</b>, <b>'mitm'</b>, <b>'io'</b>, <b>'le_secure'</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_ADVERTISE = "Démarre la publicité à un intervalle en microsecondes (arrondi au multiple de 625µs inférieur). Arrêt avec <b>interval_us=None</b>. <b>adv_data</b>/<b>resp_data</b> doivent supporter le buffer protocol ; <b>None</b> réutilise le payload précédent ; <b>b''</b> efface.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_CONNECT = "Se connecte à un périphérique via son adresse (addr_type issu du scan). Annule une tentative avec <b>gap_connect(None)</b>. Succès : <b>_IRQ_PERIPHERAL_CONNECT</b> ; annulation/déconnexion : <b>_IRQ_PERIPHERAL_DISCONNECT</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_DISCONNECT = "Déconnecte un pair (central ou périphérique selon le rôle). émet <b>_IRQ_PERIPHERAL_DISCONNECT</b> ou <b>_IRQ_CENTRAL_DISCONNECT</b>. Returns <b>True</b> si le handle était connecté, sinon <b>False</b>. Returns: <b>bool</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_PAIR = "Initie l'appairage avec l'appareil distant. Configurer <b>io</b>, <b>mitm</b>, <b>le_secure</b>, <b>bond</b> avant. Succès : <b>_IRQ_ENCRYPTION_UPDATE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_PASSKEY = "Répond à un événement <b>_IRQ_PASSKEY_ACTION</b> (I/O du code). L'action indique s'il faut saisir, afficher, ou confirmer une comparaison numérique.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_SCAN = "Scanne pendant <b>duration_ms</b> (0 = infini, None = stop). Configure le duty cycle avec <b>interval_us</b>/<b>window_us</b>. émet <b>_IRQ_SCAN_RESULT</b> avec (<b>addr_type</b>, <b>addr</b>, <b>adv_type</b>, <b>rssi</b>, <b>adv_data</b>) puis <b>_IRQ_SCAN_DONE</b> en fin.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_DISCOVER_CHARACTERISTICS = "Découvre les caractéristiques dans une plage de handles (filtre <b>uuid</b> optionnel). émet <b>_IRQ_GATTC_CHARACTERISTIC_RESULT</b> puis <b>_IRQ_GATTC_CHARACTERISTIC_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_DISCOVER_DESCRIPTORS = "Découvre les descripteurs dans une plage de handles. émet <b>_IRQ_GATTC_DESCRIPTOR_RESULT</b> puis <b>_IRQ_GATTC_DESCRIPTOR_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_DISCOVER_SERVICES = "Découvre les services d'un serveur connecté (filtre <b>uuid</b> optionnel). émet <b>_IRQ_GATTC_SERVICE_RESULT</b> puis <b>_IRQ_GATTC_SERVICE_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_EXCHANGE_MTU = "Initie l'échange MTU ATT avec le MTU préféré défini par <b>config(mtu=value)</b>. émet <b>_IRQ_MTU_EXCHANGED</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_READ = "Lance une lecture distante. émet <b>_IRQ_GATTC_READ_RESULT</b> puis <b>_IRQ_GATTC_READ_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_WRITE = "Lance une écriture distante. <b>mode=0</b> sans réponse (aucun event). <b>mode=1</b> avec réponse ; à la réponse : <b>_IRQ_GATTC_WRITE_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_INDICATE = "Envoie une indication à un client connecté. Si <b>data</b> est None, envoie la valeur locale courante ; sinon envoie <b>data</b>. \u00c0 l'ack/échec : <b>_IRQ_GATTS_INDICATE_DONE</b>. Envoyé quel que soit le statut d'abonnement.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_NOTIFY = "Envoie une notification à un client connecté. Si <b>data</b> est None, envoie la valeur locale courante ; sinon envoie <b>data</b>. Envoyé quel que soit le statut d'abonnement.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_READ = "Lit la valeur locale d'un handle (écrite par <b>gatts_write</b> ou un client distant). Returns: <b>bytes</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_REGISTER_SERVICES = "Enregistre des services/caractéristiques GATT serveur (remplace l'existant). Retourne une liste de tuples de handles (aplatis). Note : il faut arrêter l'advertising avant. Returns: <b>list</b>.";
